codon_table = {}
bases = "TCAG"
aas = "FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
i = 0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            codon_table[b1+b2+b3] = aas[i]
            i += 1

def translate(s):
    return "".join(codon_table.get(s[j:j+3], "X") for j in range(0, len(s)-2, 3))

def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def find_orfs(s, minlen=150):
    orfs = []
    n = len(s)
    for strand, seseq in [("+", s), ("-", revcomp(s))]:
        for frame in range(3):
            i = frame
            while i < n - 2:
                codon = seseq[i:i+3]
                if codon == "ATG":
                    # scan for stop
                    j = i
                    prot = ""
                    while j + 3 <= n:
                        aa = codon_table.get(seseq[j:j+3], "X")
                        if aa == "*":
                            break
                        prot += aa
                        j += 3
                    if len(prot) >= minlen//3 - 1:
                        if strand == "+":
                            orfs.append((i+1, j+3, strand, len(prot), prot))
                        else:
                            # coordinate on reverse strand -> report on plus strand
                            start_plus = n - (j+3) + 1
                            end_plus = n - i
                            orfs.append((start_plus, end_plus, strand, len(prot), prot))
                    i = j + 3
                else:
                    i += 3
    return orfs

orfs = find_orfs(dna, minlen=150)
orfs.sort(key=lambda x: -x[3])
