# find self-alignments: for each shift, align seq to itself and count identity
best_shifts = []
for shift in range(30, n-100):
    L = n - shift
    a = dna[:L]
    b = dna[shift:shift+L]
    matches = sum(1 for x,y in zip(a,b) if x==y)
    identity = matches / L
    if identity > 0.70:
        best_shifts.append((shift, identity, matches, L))
if not best_shifts:
    print("no self-similarity >70% at any shift")
